<script setup lang="ts">
import {ref} from 'vue';import {api} from '../api';import {displayText} from '../stores/presentation';import type {Case} from '../types';import BankingCards from './BankingCards.vue'
const props=defineProps<{c:Case;disabled:boolean}>(),emit=defineEmits(['changed'])
const items=ref((props.c.data.bank_accounts||[]).map((a:any,i:number)=>({account_index:i,document_id:a.statement_reference||'',ownership_verified:a.ownership_status==='Reviewed by officer',notes:a.review_notes||''}))),busy=ref(false),error=ref('')
async function save(){busy.value=true;error.value='';try{await api('/applications/'+props.c.id+'/bank-review',{revision:props.c.revision,items:items.value});emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script><template><section v-if="items.length" class="panel"><BankingCards :accounts="c.data.bank_accounts||[]"/><details><summary>Review account ownership & link statements</summary><form @submit.prevent="save"><p>Match the account-holder name and account reference against each source statement before confirming ownership.</p><fieldset v-for="(item,i) in items" :key="i"><legend>{{c.data.bank_accounts?.[i].bank_name}} · {{c.data.bank_accounts?.[i].account_last4}}</legend><label>Source statement<select v-model="item.document_id" required><option disabled value="">Select processed statement</option><option v-for="d in (c.documents||[]).filter(d=>d.kind==='bank'&&d.status==='parsed')" :value="d.id">{{displayText(d.name)}} · {{d.id.slice(0,8)}}</option></select></label><label class="checkbox"><input type="checkbox" v-model="item.ownership_verified">Account ownership checked against source evidence</label><label>Review notes<textarea v-model="item.notes" minlength="3" maxlength="500" required></textarea></label></fieldset><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="disabled||busy">Save banking review</button><small>Saving updates the case revision. Run analysis again to include the review in the memo.</small></form></details></section></template>